type Json = any;

function isPlainObject(value: any): value is Record<string, Json> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function deepEqual(a: Json, b: Json): boolean {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const keysA = Object.keys(a).sort();
    const keysB = Object.keys(b).sort();
    if (keysA.length !== keysB.length) return false;
    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
      if (!deepEqual(a[key], b[key])) return false;
    }
    return true;
  }
  return false;
}

function deepMerge(a: Json, b: Json): Json {
  if (Array.isArray(a) && Array.isArray(b)) {
    const result: Json[] = [];
    for (const item of [...a, ...b]) {
      if (!result.some((existing) => deepEqual(existing, item))) {
        result.push(item);
      }
    }
    return result;
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const result: Record<string, Json> = { ...a };
    for (const key of Object.keys(b)) {
      if (Object.prototype.hasOwnProperty.call(a, key)) {
        result[key] = deepMerge(a[key], b[key]);
      } else {
        result[key] = b[key];
      }
    }
    return result;
  }
  return b;
}

function sortJson(value: Json): Json {
  if (Array.isArray(value)) {
    return value.map((item) => sortJson(item));
  }
  if (isPlainObject(value)) {
    const result: Record<string, Json> = {};
    for (const key of Object.keys(value).sort()) {
      result[key] = sortJson(value[key]);
    }
    return result;
  }
  return value;
}

