    for (int i = 0; i < len; i++) {
        if (comma_pos == i && i != 0) with_commas[j++] = ',';
        with_commas[j++] = int_str[i];
        if (comma_pos == i) comma_pos += 3;
    }
    with_commas[j] = 0;
    if (with_decimals) {
        snprintf(out, out_size, "$%s.%02lld", with_commas, cents);
    } else {
        snprintf(out, out_size, "$%s", with_commas);
    }
}

