func fetchProducts(completion: @escaping ([Product]?) -> Void) {
    let url = URL(string: "http://127.0.0.1:18923/api/products")!
    var request = URLRequest(url: url)
    request.httpMethod = "GET"

    let task = URLSession.shared.dataTask(with: request) { data, response, error in
        if let error = error {
            completion(nil)
            return
        }
        guard let data = data else {
            completion(nil)
            return
        }

        do {
            let json = try JSONSerialization.jsonObject(with: data, options: [])
            var products: [Product] = []

            if let array = json as? [[String: Any]] {
                for item in array {
                    let id = (item["id"] as? NSNumber)?.intValue ?? 0
                    let name = item["name"] as? String ?? ""
                    let price = (item["price"] as? NSNumber)?.doubleValue ?? 0.0
                    let category = item["category"] as? String ?? ""
                    let stock = (item["stock"] as? NSNumber)?.intValue ?? 0
                    products.append(Product(id: id, name: name, price: price, category: category, stock: stock))
                }
            }

            completion(products)
        } catch {
            completion(nil)
        }
    }

    task.resume()
}

