int read_line(FILE *fp, char **buf, size_t *cap) {
    size_t len = 0;
    int c = fgetc(fp);
    if (c == EOF) return 0;
    while (c != EOF && c != '\n') {
        if (len + 1 >= *cap) {
            *cap *= 2;
            *buf = realloc(*buf, *cap);
        }
        (*buf)[len++] = (char)c;
        c = fgetc(fp);
    }
    (*buf)[len] = '\0';
    return 1;
}

