    let dict = edge as? [String: Any] ?? [:]
    let from = dict["from"] as? String ?? ""
    let to = dict["to"] as? String ?? ""
    let weight = (dict["weight"] as? NSNumber)?.intValue ?? 0
    if adj[from] == nil { adj[from] = [] }
    adj[from]!.append((to, weight))
    if adj[to] == nil { adj[to] = [] }
    adj[to]!.append((from, weight))
}

var dist: [String: Int] = [:]
for node in nodes {
    dist[node] = Int.max
}
dist["A"] = 0
var visited: Set<String> = []

while true {
    var current: String? = nil
    var best: Int = Int.max
    for node in dist.keys {
        if !visited.contains(node) {
            let d = dist[node] ?? Int.max
            if d < best {
                best = d
                current = node
            }
        }
    }
    guard let u = current else { break }
    visited.insert(u)
    if best == Int.max { break }
    let du = dist[u] ?? 0
    if let neighbors = adj[u] {
        for item in neighbors {
            let v = item.0
            let w = item.1
            if !visited.contains(v) {
                let dv = dist[v] ?? Int.max
                if du + w < dv {
                    dist[v] = du + w
                }
            }
        }
    }
