  to: string;
  weight: number;
}

const graphPath = '__FIXTURE_DIR__/graph.json';
const data = JSON.parse(readFileSync(graphPath, 'utf8'));

const nodes: string[] = data.nodes;
const edges: Edge[] = data.edges;

const graph = new Map<string, Adjacency[]>();

for (const node of nodes) {
  graph.set(node, []);
}

for (const edge of edges) {
  if (!graph.has(edge.from)) graph.set(edge.from, []);
  if (!graph.has(edge.to)) graph.set(edge.to, []);

  graph.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
  graph.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
}

const distances = new Map<string, number>();
const visited = new Set<string>();

for (const node of nodes) {
  distances.set(node, Infinity);
}

distances.set('A', 0);

while (true) {
  let current: string | null = null;
  let currentDistance = Infinity;

  for (const node of nodes) {
    const distance = distances.get(node)!;
    if (!visited.has(node) && distance < currentDistance) {
      currentDistance = distance;
      current = node;
    }
  }

  if (current === null) break;
  if (currentDistance === Infinity) break;

  visited.add(current);

  const neighbors = graph.get(current) || [];
  for (const neighbor of neighbors) {
    const newDistance = currentDistance + neighbor.weight;
    const knownDistance = distances.get(neighbor.to)!;

    if (newDistance < knownDistance) {
      distances.set(neighbor.to, newDistance);
    }
  }
}

const sortedNodes = [...nodes].sort((a, b) => a.localeCompare(b));
const outputLines: string[] = [];

for (const node of sortedNodes) {
  const distance = distances.get(node);
  outputLines.push(`A -> ${node}: ${distance}`);
}

