    static int[][] multiply(int[][] A, int[][] B) {
        int n = A.length;
        int m = B[0].length;
        int p = B.length;
        int[][] C = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int sum = 0;
                for (int k = 0; k < p; k++) {
                    sum += A[i][k] * B[k][j];
                }
                C[i][j] = sum;
            }
        }
        return C;
    }

    static long determinant(int[][] M) {
        return (long) M[0][0] * (M[1][1]*M[2][2] - M[1][2]*M[2][1])
             - (long) M[0][1] * (M[1][0]*M[2][2] - M[1][2]*M[2][0])
             + (long) M[0][2] * (M[1][0]*M[2][1] - M[1][1]*M[2][0]);
    }

    static void printMatrix(int[][] M) {
        for (int i = 0; i < M.length; i++) {
            StringBuilder sb = new StringBuilder("  ");
            for (int j = 0; j < M[i].length; j++) {
                if (j > 0) sb.append(" ");
                sb.append(String.format("%4d", M[i][j]));
            }
            System.out.println(sb.toString());
        }
    }
}

function formatMatrix(matrix: number[][]): string {
  return matrix.map(row => "  " + row.map(v => v.toString().padStart(4, " ")).join(" ")).join("\n");
}

function multiply(A: number[][], B: number[][]): number[][] {
  const n = A.length;
  const m = B[0].length;
  const p = A[0].length;
  const result: number[][] = Array.from({ length: n }, () => Array(m).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      let sum = 0;
      for (let k = 0; k < p; k++) {
        sum += A[i][k] * B[k][j];
      }
      result[i][j] = sum;
    }
  }
  return result;
}

function determinant3x3(mat: number[][]): number {
  const a = mat[0][0], b = mat[0][1], c = mat[0][2];
  const d = mat[1][0], e = mat[1][1], f = mat[1][2];
  const g = mat[2][0], h = mat[2][1], i = mat[2][2];
  return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}

